const input=$json.body??$json;
const offer=input.offer_package??{};
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const channel=String(input.channel||input.communication_channel||"").toLowerCase();
const recipient=String(input.recipient||input.seller_phone||input.seller_email||"").trim();
const message=String(input.message||input.offer_message||"").trim();
const offerPrice=Number(offer.opening_offer??input.offer_price);
const mao=Number(offer.dynamic_mao??input.dynamic_mao);
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id);
const channelValid=["sms","email"].includes(channel);
const recipientValid=recipient.length>0;
const offerValid=Number.isFinite(offerPrice)&&Number.isFinite(mao)&&offerPrice<=mao;
const eligible=input.status==="offer_package_ready"||input.offer_package_ready===true;
const dnc=Boolean(input.dnc||input.do_not_contact);
const ready=identityComplete&&eligible&&channelValid&&recipientValid&&message.length>0&&offerValid&&!dnc&&blockers.length===0;
const dispatchId=input.dispatch_id||`wf289-${input.deal_id||"unknown"}-${input.property_id||"none"}-${input.version||1}`;
const idempotencyKey=input.idempotency_key||`offer-dispatch:${dispatchId}`;
let status="dispatch_ready",nextWorkflow="WF-290",humanReview=true,reason="offer is prepared for controlled dispatch";
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";reason="missing deal/lead/property identity";}
else if(dnc){status="dnc_blocked";nextWorkflow="WF-126";reason="seller is marked do-not-contact";}
else if(blockers.length){status="dispatch_blocked";nextWorkflow="WF-126";reason="active blockers present";}
else if(!eligible){status="offer_package_required";nextWorkflow="WF-288";reason="offer package is not ready";}
else if(!channelValid||!recipientValid||!message.length){status="dispatch_data_missing";nextWorkflow="WF-288";reason="channel, recipient, or message is missing";}
else if(!offerValid){status="mao_guardrail_violation";nextWorkflow="WF-287";reason="offer price exceeds dynamic MAO";}
const dispatch={dispatch_id:dispatchId,idempotency_key:idempotencyKey,channel,recipient,offer_price:offerPrice,dynamic_mao:mao,message_present:Boolean(message.length),delivery_receipt_required:true,provider_execution_required:true,provider_credentials_runtime_only:true};
return [{json:{...input,workflow:"WF-289",workflow_name:"Seller Offer Package → Offer Dispatch, Delivery Receipt & Negotiation State Controller",status,dispatch,next_workflow:nextWorkflow,human_review_required:humanReview,audit:{event_type:"offer_dispatch_delivery_negotiation_state",idempotency_key:idempotencyKey,dispatch_id:dispatchId}}}];
